import type { Column, Typed } from '../Column'

/**
 * A Column for a version type field.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @group Table/Columns
 */
export function VersionColumn<
    const Type extends `${bigint}.${bigint}.${bigint}`,
    const Default extends Type,
    const C extends Column<Type, Default>,
>(config: C & Column<Type, Default>) {
    return config as Typed<Type, C>
}
